// 1. CAPTURA DOS DADOS DE ENTRADA
const inputJson = $input.first().json;
const dadosCliente = inputJson.cliente || {};

// 2. VERIFICAÇÃO DE STATUS (INATIVO OU BLOQUEADO)
const estaInativo = dadosCliente.inativo === true || dadosCliente.inativo === "Sim";
const estaBloqueado = dadosCliente.bloqueado === true || dadosCliente.bloqueado === "Sim";

if (estaInativo || estaBloqueado) {
    return {
        ...inputJson,
        mensagem_confirmacao: "Atenção",
        mensagem_texto: "Prezado cliente, identificamos uma pendência administrativa em seu cadastro que impede a consulta automática de dados. Vamos transferir seu chat para um atendente.",
        proximo_estado: "Menu_Principal",
        rota_destino: "cliente_bloqueado",
        sucesso: false
    };
}

// 2.1 CAPTURA A MENSAGEM DO "AGORA"
const msgWebhook = $('get_data').first().json.conversation || "";
const rawMsg = msgWebhook.toLowerCase().trim();
const msgNum = rawMsg.replace(/\D/g, '');

// 3. REFERÊNCIAS DO CONTEXTO
const menuSalvo = inputJson.navegacao?.menu_atual || "Menu_Principal";
const nomeUsuario = inputJson.auth?.nome || "Cliente";

const prefixoErro = "*Opção inválida.*\n\nA resposta enviada não corresponde a nenhuma opção disponível. Selecione uma das opções abaixo:\n\n";
const rodapeBoleto = "Digite o número da opção para receber o PDF da fatura desejada.\n\n━━━━━━━━━━━━━━━━━━\n9 - Falar com atendente\n0 - Voltar ao menu";

const montarMsgErroBoleto = (ctx) => {
  const lista = ctx.navegacao?.texto_lista_faturas || "";
  return prefixoErro + lista + (lista ? "\n\n" : "") + rodapeBoleto;
};

const montarMsgErroMenu = (textoMenu) => prefixoErro + (textoMenu || "Por favor, envie apenas o número correspondente à opção desejada.");

// --- 4. DICIONÁRIO DE MENUS ---
const menuPrincipal = {
  nome: "Menu_Principal",
  msg: `*MENU PRINCIPAL*
━━━━━━━━━━━━━━━━━━
Olá, *${nomeUsuario}*!
Como posso te ajudar hoje?

1 - *Minhas faturas*
2 - *Meus CCR* (Comprovantes)
3 - *MTR* (Manifestos)
4 - *Meus contratos*
9 - *Falar com atendente*

━━━━━━━━━━━━━━━━━━
Digite *Sair* para encerrar o atendimento.`,
  opcoes: {
    "1": { prox: "Buscando_Faturas", rota: "buscar_faturas" },
    "2": { prox: "Meus_CCR", rota: "menu_ccr" },
    "3": { prox: "Menu_MTR", rota: "abrir_menu" },
    "4": { prox: "Meus_Contratos", rota: "menu_contrato" },
    "9": { prox: "Atendimento_Humano", rota: "ir_atendimento" }
  }
};

const menuCCR = {
  nome: "Meus_CCR",
  msg: `*MEUS COMPROVANTES (CCR)*
━━━━━━━━━━━━━━━━━━
Como deseja visualizar suas últimas coletas?

1 - Último CCR
2 - Últimos 3 CCRs
3 - Últimos 6 CCRs

━━━━━━━━━━━━━━━━━━
9 - Falar com atendente
0 - Voltar ao menu anterior`,
  opcoes: {
    "1": { prox: "Buscando_CCR_1", rota: "buscar_ccr" },
    "2": { prox: "Buscando_CCR_3", rota: "buscar_ccr" },
    "3": { prox: "Buscando_CCR_6", rota: "buscar_ccr" },
    "9": { prox: "Atendimento_Humano", rota: "ir_atendimento" },
    "0": { prox: "Menu_Principal", rota: "abrir_menu" }
  }
};

const mapaMenus = {
  "Menu_Principal": menuPrincipal,
  "Meus_CCR": menuCCR,
  "nenu_ccr": menuCCR,
  "buscar_ccr": menuCCR,
  "selecione_boleto": {
    msg: rodapeBoleto,
    opcoes: {
      "0": { prox: "Menu_Principal", rota: "abrir_menu" },
      "9": { prox: "Atendimento_Humano", rota: "ir_atendimento" }
    }
  },
  "fluxo_finalizado": {
    msg: "1 - Iniciar novo atendimento\n2 - Falar com atendente",
    opcoes: {
      "1": { prox: "Menu_Principal", rota: "abrir_menu" },
      "2": { prox: "Atendimento_Humano", rota: "ir_atendimento" }
    }
  }
};

// --- 5.1 MENU DE CCR ---
if ((menuSalvo === "buscar_ccr" || menuSalvo === "Meus_CCR" || menuSalvo === "nenu_ccr") && msgNum !== "0" && msgNum !== "9" && msgNum !== "") {
    const mapaQuantidade = { "1": 1, "2": 3, "3": 6 };
    const qtdSelecionada = mapaQuantidade[msgNum];

    if (qtdSelecionada) {
        return {
            ...inputJson,
            mensagem_confirmacao: `Opção ${msgNum} selecionada.`,
            mensagem_texto: `Estou localizando os seus últimos ${qtdSelecionada} CCRs. Aguarde um momento...`,
            quantidade_ccr: qtdSelecionada,
            rota_destino: "buscar_ccr",
            sucesso: true
        };
    }

    return {
        ...inputJson,
        mensagem_confirmacao: "Opção inválida",
        mensagem_texto: montarMsgErroMenu(menuCCR.msg),
        proximo_estado: menuSalvo === "buscar_ccr" ? "buscar_ccr" : "Meus_CCR",
        rota_destino: "fallback",
        sucesso: false
    };
}

// --- 5.2 MENU DE BOLETOS ---
if (menuSalvo === "selecione_boleto" && msgNum !== "0" && msgNum !== "9" && msgNum !== "") {
    const faturas = inputJson.navegacao?.faturas_disponiveis || [];
    const escolhaUsuario = msgNum.trim();
    const faturaAchada = faturas.find(f => f.indice.toString() === escolhaUsuario);

    if (faturaAchada) {
        return {
            ...inputJson,
            mensagem_confirmacao: `Boleto ${msgNum} selecionado.`,
            mensagem_texto: `Localizei o boleto ${faturaAchada.numero_boleto}. Estou gerando o arquivo para você...`,
            idFatura: faturaAchada.boleto_id,
            rota_destino: "selecione_boleto",
            sucesso: true
        };
    }

    return {
        ...inputJson,
        mensagem_confirmacao: "Opção inválida",
        mensagem_texto: montarMsgErroBoleto(inputJson),
        proximo_estado: "selecione_boleto",
        rota_destino: "fallback",
        sucesso: false
    };
}

// --- 5.3 NAVEGAÇÃO GERAL ---
let menuAtual = mapaMenus[menuSalvo] || mapaMenus["Menu_Principal"];
let selecao = menuAtual.opcoes[msgNum];

if (selecao && msgNum !== "") {
  if (selecao.rota === "buscar_faturas") {
    return {
      ...inputJson,
      mensagem_confirmacao: "Minhas Faturas selecionado",
      mensagem_texto: "Aguarde. Estamos buscando suas faturas.",
      proximo_estado: "Buscando_Faturas",
      rota_destino: "buscar_faturas",
      sucesso: true
    };
  }

  let proximoMenu = mapaMenus[selecao.prox] || mapaMenus["Menu_Principal"];
  return {
    ...inputJson,
    mensagem_confirmacao: "Processando",
    mensagem_texto: proximoMenu.msg || menuPrincipal.msg,
    proximo_estado: selecao.prox,
    rota_destino: selecao.rota,
    sucesso: true
  };
}

if (menuSalvo === "selecione_boleto") {
  return {
    ...inputJson,
    mensagem_confirmacao: "Opção inválida",
    mensagem_texto: montarMsgErroBoleto(inputJson),
    proximo_estado: "selecione_boleto",
    rota_destino: "fallback",
    sucesso: false
  };
}

return {
  ...inputJson,
  mensagem_confirmacao: "Opção inválida",
  mensagem_texto: montarMsgErroMenu(menuAtual.msg),
  proximo_estado: menuSalvo,
  rota_destino: "fallback",
  sucesso: false
};

