// 1. Captura a resposta da API (acessando a primeira posição do array retornado)
const resposta = $input.first().json;

// Busca o array de coletas dentro do campo 'dados' da nova API
const listaCcr = resposta.dados || [];

// VERIFICAÇÃO: Se a API retornou sucesso = false ou se a lista de dados veio vazia
if (resposta.sucesso === false || listaCcr.length === 0) {
  return { 
    texto_ccr: "Nenhuma coleta foi localizada para o seu cadastro no momento." 
  };
}

// 2. Monta o cabeçalho
let mensagem = `*CCRs LOCALIZADOS (${listaCcr.length})*\n`;
mensagem += "━━━━━━━━━━━━━━━━━━\n\n";

// 3. Percorre a lista e adiciona cada item formatado
listaCcr.forEach((item, index) => {
    // Formata a data convertendo o padrão ISO da nova API
    const data = new Date(item.datacoleta).toLocaleDateString('pt-BR', { timeZone: 'UTC' });

    // Verifica a quantidade usando o novo nome da propriedade
    const quantidade = item.quantidade > 0 ? `${item.quantidade} un/kg` : "Consulte no PDF";

    mensagem += `${index + 1}️⃣ *Coleta em ${data}*\n`;
    mensagem += `*Qtd:* ${quantidade}\n`;
    mensagem += `🔗 *Link:* ${item.link}\n\n`;
});

mensagem += "━━━━━━━━━━━━━━━━━━\n";
mensagem += "_Clique nos links acima para visualizar os documentos._";

return {
    texto_ccr: mensagem
};

