// 1. Captura a entrada do n8n
const entrada = $input.first().json;

let faturas = [];
let sucesso = false;

// BLINDAGEM: Testa se a estrutura veio envelopada em array ou como objeto direto
if (Array.isArray(entrada)) {
  sucesso = entrada[0]?.sucesso;
  faturas = entrada[0]?.dados || [];
} else if (entrada.dados) {
  sucesso = entrada.sucesso;
  faturas = entrada.dados || [];
} else if (entrada.body && entrada.body.dados) { // Caso venha dentro do 'body' do HTTP Request
  sucesso = entrada.body.sucesso;
  faturas = entrada.body.dados || [];
}

// VERIFICAÇÃO: Se a esteira falhou ou o array de dados reais está zerado
if (sucesso === false || faturas.length === 0) {
  return [{
    json: {
      texto_final: "*CONSULTA DE CONTRATOS*\n━━━━━━━━━━━━━━━━━━\n\nNão localizamos contratos ativos ou anteriores vinculados ao seu cadastro no momento.\n\n━━━━━━━━━━━━━━━━━━\nDigite *0* para voltar ao menu principal.",
      contratos_mapeados: [],
      sucesso_busca: false
    }
  }];
}

// 2. Formata a lista e mapeia para o Redis
let listaFormatada = "📜 *CONTRATOS LOCALIZADOS*\n━━━━━━━━━━━━━━━━━━\n\n";
let contratosMapeados = [];

faturas.forEach((item, index) => {
  const opcao = index + 1;

  const dataValidade = new Date(item.validade).toLocaleDateString('pt-BR', { timeZone: 'UTC' });
  const situacaoAtual = item.situacao || "";
  const statusIcon = situacaoAtual.toLowerCase() === "ativo" ? "🟢" : "🔴";
  const statusTexto = `*${situacaoAtual}*`;

  listaFormatada += `${opcao}️⃣ *Contrato:* ${item.numeroContrato}\n`;
  listaFormatada += `📅 *Validade:* ${dataValidade}\n`;
  listaFormatada += `📌 *Status:* ${statusIcon} ${statusTexto}\n\n`;

  contratosMapeados.push({
    indice: opcao,
    contrato_id: item.idContrato,
    numero_contrato: item.numeroContrato,
    validade: dataValidade
  });
});

listaFormatada += "━━━━━━━━━━━━━━━━━━\n";


return [{
  json: {
    texto_final: listaFormatada,
    contratos_mapeados: contratosMapeados,
    sucesso_busca: true
  }
}];

