// 1. CAPTURA FIXA DO MERGE
const dadosMerge = $('Merge1').first().json.dados_sessao;

let estadoAuth = 'inicio';
let menuAtual = '';
let sessaoObjeto = {};

try {
  sessaoObjeto = typeof dadosMerge === 'string'
    ? JSON.parse(dadosMerge)
    : (dadosMerge || {});

  estadoAuth = sessaoObjeto?.auth?.estado_anterior || 'inicio';
  menuAtual = sessaoObjeto?.navegacao?.menu_atual ?? '';
} catch (e) {
  estadoAuth = 'inicio';
  menuAtual = '';
  sessaoObjeto = {};
}

// Prioridade: mensagem contextual gerada pelo menu3 no fallback de menu
let menu3Data = null;
try {
  menu3Data = $('menu3').first().json;
  if (menu3Data?.rota_destino === 'fallback' && menu3Data?.mensagem_texto) {
    return [{
      json: {
        texto_erro: menu3Data.mensagem_texto,
        estado_validado: estadoAuth,
        menu_validado: menuAtual
      }
    }];
  }
} catch (e) {}

const prefixoErro = '*Opção inválida.*\n\nA resposta enviada não corresponde a nenhuma opção disponível. Selecione uma das opções abaixo:\n\n';

const menuPrincipalMsg = `*MENU PRINCIPAL*
━━━━━━━━━━━━━━━━━━
Como posso te ajudar hoje?

1 - *Minhas faturas*
2 - *Meus CCR* (Comprovantes)
3 - *MTR* (Manifestos)
4 - *Meus contratos*
9 - *Falar com atendente*

━━━━━━━━━━━━━━━━━━
Digite *Sair* para encerrar o atendimento.`;

const menuCCRMsg = `*MEUS COMPROVANTES (CCR)*
━━━━━━━━━━━━━━━━━━
Como deseja visualizar suas últimas coletas?

1 - Último CCR
2 - Últimos 3 CCRs
3 - Últimos 6 CCRs

━━━━━━━━━━━━━━━━━━
9 - Falar com atendente
0 - Voltar ao menu anterior`;

const menuBuscarCCRMsg = `*CCRs DISPONÍVEIS*
━━━━━━━━━━━━━━━━━━
Como deseja receber?

1 - Último CCR
2 - Últimos 3 CCRs
3 - Últimos 6 CCRs
━━━━━━━━━━━━━━━━━━

9 - Falar com atendente
0 - Voltar ao menu`;

const rodapeBoleto = `Digite o número da opção para receber o PDF da fatura desejada.

━━━━━━━━━━━━━━━━━━
9 - Falar com atendente
0 - Voltar ao menu`;

let mensagem = '';

if (estadoAuth === 'cliente_novo' || (menuAtual === '' && estadoAuth !== 'autenticado_autorizado')) {
  mensagem = 'Não foi possível compreender sua resposta.\n\nPor favor, responda apenas *1* para SIM ou *2* para NÃO para nos informar se você já possui cadastro conosco.';
} else if (estadoAuth === 'token_invalido' || estadoAuth === 'TOKEN_EXPIRADO') {
  mensagem = '*SESSÃO EXPIRADA*\n━━━━━━━━━━━━━━━━━━\n\nSua sessão expirou por tempo limite atingido.\n\nPor favor, envie qualquer mensagem de texto para reiniciar o seu processo de identificação.';
} else if (estadoAuth === 'autorizado') {
  mensagem = '*Opção inválida.*\n\nPor favor, digite apenas *1* se deseja confirmar a validação dos seus dados ou *2* caso queira cancelar.';
} else if (estadoAuth === 'AGUARDANDO_CPF') {
  mensagem = 'O CPF ou CNPJ informado não foi localizado em nosso sistema ou está inconsistente.\n\nPor favor, certifique-se de enviar *apenas os números* do documento cadastrado na plataforma.';
} else if (estadoAuth === 'AGUARDANDO_CONFIRMAR') {
  mensagem = '*Confirmação de Segurança*\n\nO dado informado não confere com o CPF do responsável pela empresa.\n\nPor favor, digite apenas os *4 primeiros dígitos* do CPF do titular do cadastro para liberar o acesso.';
} else if (menuAtual === 'selecione_boleto') {
  const listaFaturas = sessaoObjeto?.navegacao?.texto_lista_faturas || '';
  mensagem = prefixoErro + listaFaturas + (listaFaturas ? '\n\n' : '') + rodapeBoleto;
} else if (menuAtual === 'buscar_ccr') {
  mensagem = prefixoErro + menuBuscarCCRMsg;
} else if (menuAtual === 'Meus_CCR' || menuAtual === 'nenu_ccr') {
  mensagem = prefixoErro + menuCCRMsg;
} else if (menuAtual === 'Menu_Principal' || estadoAuth === 'autenticado_autorizado') {
  mensagem = prefixoErro + menuPrincipalMsg;
} else if (menuAtual === 'fluxo_finalizado') {
  mensagem = prefixoErro + '1 - Iniciar novo atendimento\n2 - Falar com atendente';
} else {
  mensagem = 'Não foi possível localizar essa opção no menu.\n\nPor favor, envie apenas o *número* correspondente à opção desejada ou digite *Sair* a qualquer momento para finalizar.';
}

return [{
  json: {
    texto_erro: mensagem,
    estado_validado: estadoAuth,
    menu_validado: menuAtual
  }
}];

