// 1. Captura a resposta da API do nó anterior
const respostaApi = $input.first().json;

// Extrai o token usando a chave exata do seu retorno ("token")
const token = respostaApi.token; 

if (!token) {
  return [{ 
    json: { 
      sucesso_decode: false, 
      erro: "Token não encontrado na resposta da API." 
    } 
  }];
}

try {
  // Isola o payload (segunda parte do JWT)
  const base64Url = token.split('.')[1];

  // Normaliza o padrão Base64Url para Base64 tradicional
  const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');

  // Decodifica o Base64 para string UTF-8 Puro
  const payloadTexto = Buffer.from(base64, 'base64').toString('utf-8');

  // Converte a string em objeto real
  const dadosDecodificados = JSON.parse(payloadTexto);

  // 2. Retorna os dados mastigados para o fluxo do n8n
  return [{
    json: {
      sucesso_decode: true,
      tipo_token: respostaApi.tipo || "Bearer",
      expira_em_minutos: respostaApi.expiraEmMinutos || 15,
      cliente: {
        id: dadosDecodificados.id_client || dadosDecodificados.id_cliente,
        nome_responsavel: dadosDecodificados.responsavel,
        cpf: dadosDecodificados.cpf,
        email: dadosDecodificados.email,
        senha: dadosDecodificados.senha,
        bloqueado: dadosDecodificados.bloqueado,
        inativo: dadosDecodificados.inativo
      },
      exp_timestamp: dadosDecodificados.exp
    }
  }];

} catch (error) {
  return [{ 
    json: { 
      sucesso_decode: false, 
      erro: "Falha ao decodificar o token JWT: " + error.message 
    } 
  }];
}

